import{json,ensureAdminSchema,hashPassword,randomToken,sha256,sessionCookie}from'../../_auth.js';
export async function onRequestGet(context){try{await ensureAdminSchema(context);const r=await context.env.DB.prepare('SELECT COUNT(*) n FROM website_admin_users').first();return json({ok:true,needsSetup:Number(r?.n||0)===0})}catch(e){return json({ok:false,error:'Không thể kiểm tra trạng thái khởi tạo.',detail:String(e?.message||e)},{status:503})}}
export async function onRequestPost(context){try{await ensureAdminSchema(context);const count=await context.env.DB.prepare('SELECT COUNT(*) n FROM website_admin_users').first();if(Number(count?.n||0)>0)return json({ok:false,error:'Hệ thống đã được khởi tạo.'},{status:409});const b=await context.request.json().catch(()=>({}));const name=String(b.name||'').trim(),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||''),confirm=String(b.confirmPassword||'');if(name.length<2||!/^\S+@\S+\.\S+$/.test(email))return json({ok:false,error:'Vui lòng nhập tên và email hợp lệ.'},{status:400});if(password.length<10||!/[A-Z]/.test(password)||!/[a-z]/.test(password)||!/[0-9]/.test(password))return json({ok:false,error:'Mật khẩu cần từ 10 ký tự, có chữ hoa, chữ thường và số.'},{status:400});if(password!==confirm)return json({ok:false,error:'Mật khẩu xác nhận không khớp.'},{status:400});const id=crypto.randomUUID(),salt=randomToken(18),iterations=180000,hash=await hashPassword(password,salt,iterations);await context.env.DB.prepare(`INSERT INTO website_admin_users(id,email,name,role,status,password_salt,password_hash,password_iterations,must_change_password) VALUES(?,?,?,'owner','active',?,?,?,1)`).bind(id,email,name,salt,hash,iterations).run();const token=randomToken(),th=await sha256(token),exp=new Date(Date.now()+30*864e5).toISOString();await context.env.DB.prepare('INSERT INTO website_admin_sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').bind(th,id,exp).run();return json({ok:true,user:{id,email,name,role:'owner',status:'active',mustChangePassword:true}},{headers:{'set-cookie':sessionCookie(token)}})}catch(e){return json({ok:false,error:'Không thể khởi tạo hệ thống.',detail:String(e?.message||e)},{status:500})}}
